#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int N;
vector<vector<int>> adj;

// Retorna as distâncias de um nó de origem e também preenche o vetor de pais
void bfs(int src, vector<int>& dist, vector<int>& parent) {
    dist.assign(N + 1, -1);
    parent.assign(N + 1, -1);
    queue<int> q;

    dist[src] = 0;
    q.push(src);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }
}

// DFS para contar vértices a uma profundidade exata
long long count_at_depth(int u, int p, int d, int target_depth) {
    if (d == target_depth) return 1;
    long long count = 0;
    for (int v : adj[u]) {
        if (v != p) {
            count += count_at_depth(v, u, d + 1, target_depth);
        }
    }
    return count;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> N)) return 0;

    adj.resize(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // 1. BFS a partir do vértice 1 para encontrar uma extremidade A
    vector<int> dist, parent;
    bfs(1, dist, parent);

    int A = 1;
    for (int i = 1; i <= N; ++i) {
        if (dist[i] > dist[A]) {
            A = i;
        }
    }

    // 2. BFS a partir de A para encontrar a outra extremidade B e o diâmetro
    bfs(A, dist, parent);

    int B = A;
    for (int i = 1; i <= N; ++i) {
        if (dist[i] > dist[B]) {
            B = i;
        }
    }

    int D = dist[B];

    // Reconstrói o caminho de B até A
    vector<int> path;
    int curr = B;
    while (curr != -1) {
        path.push_back(curr);
        curr = parent[curr];
    }
    // O caminho vai de B a A, então path[0] = B, path[D] = A.

    long long ways = 0;

    if (D % 2 == 0) {
        // Um único centro
        int center = path[D / 2];
        int target = D / 2;

        long long sum = 0;
        long long sum_sq = 0;

        for (int neighbor : adj[center]) {
            long long c = count_at_depth(neighbor, center, 1, target);
            sum += c;
            sum_sq += c * c;
        }

        ways = (sum * sum - sum_sq) / 2;
    } else {
        // Dois centros
        int c1 = path[D / 2];
        int c2 = path[D / 2 + 1];
        int target = (D - 1) / 2;

        long long count1 = count_at_depth(c1, c2, 0, target);
        long long count2 = count_at_depth(c2, c1, 0, target);

        ways = count1 * count2;
    }

    cout << D + 1 << "\n";
    cout << ways << "\n";

    return 0;
}
